{
  "probability": 0.08,
  "range_low": 0.04,
  "range_high": 0.14,
  "summary": [
    "Posterior probability of any party or coalition achieving a 2/3 majority in 2026 is about 8%.",
    "Historical base-rate (roughly 44% in post-1990 Hungary) is revised downward by current polling volatility and system biases.",
    "Electoral-system bias toward the largest bloc and diaspora voting patterns temper chances for a 133+ seat outcome for any bloc.",
    "Opposition consolidation around TISZA and selective market optimism provide some upside, but not enough to lift the odds much above the low single digits."
  ],
  "confidence": "low",
  "narrative": "Starting from the historical base-rate, updates driven by structural biases and volatile polls pull the probability toward a low outcome. While opposition unification and market signals offer modest upside, the aggregated evidence keeps the chance of a 2/3 majority around 8% with substantial uncertainty remaining.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base-rate of achieving a two-thirds majority (133+ seats) in Hungary's National Assembly under the post-1990 electoral system; 4 successes in 9 elections."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation around TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Unified anti-Orbán front could translate into more seats for opposition, potentially reaching 133+ in some scenarios, increasing the probability of a non-Fidesz 2/3 majority."
      },
      {
        "factor": "Electoral-system bias toward the largest bloc",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "The mixed system and district redrawing tend to overrepresent the leading bloc, making a durable 2/3 majority for non-government forces less likely."
      },
      {
        "factor": "Diaspora voting patterns favoring Fidesz",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Diaspora votes historically favor Fidesz, boosting incumbent seat tally and constraining anti-Orbán paths to 133+."
      },
      {
        "factor": "Market and macro signals pricing regime change",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Investor expectations of regime change can raise turnout or alter perceptions, modestly supporting non-Orbán outcomes."
      },
      {
        "factor": "Entry of far-right and smaller parties into parliament",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "New entrants fragment the vote and complicate coalitions, reducing the odds of any single bloc crossing the 133-seat threshold."
      }
    ],
    "synthesis_rationale": "From a relatively high baseline, updates are mostly negative due to structural biases and fragmented polling, with limited positive pushes from opposition unification and market expectations. The combination yields a calibrated, low posterior of 8% for any party or coalition achieving a 2/3 majority, acknowledging correlation among factors and calibration uncertainty."
  }
}

